sparql_response:
PREFIX dbo: <http://dbpedia.org/ontology/>

SELECT DISTINCT ?inst ?country
WHERE {
  VALUES ?inst { 
    <http://dbpedia.org/resource/African_Institute_for_Future_Studies> 
    <http://dbpedia.org/resource/University_of_Kisangani> 
  }
  OPTIONAL { ?inst dbo:country ?country . }
  OPTIONAL {
    ?inst dbo:city ?city .
    ?city dbo:country ?country .
  }
}
LIMIT 100

